  const button=document.createElement('button');button.id='dreamkeys-growth-toggle';button.type='button';button.setAttribute('aria-label','Open DreamKeys Growth Assistant');button.setAttribute('aria-expanded','false');button.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.4a9 9 0 0 1-.9-4.1A8.5 8.5 0 0 1 12.5 3a8.5 8.5 0 0 1 8.5 8.5Z"/><path d="M8 11.5h9M8 15h5"/></svg>';
  const frame=document.createElement('iframe');frame.id='dreamkeys-growth-frame';frame.title='DreamKeys Growth Assistant';frame.setAttribute('loading','eager');
